function getNavIcon(key: ParentNavItem['key']) {
  switch (key) {
    case 'home':
      return <HomeIcon />
    case 'observations':
      return <ClipboardIcon />
    case 'report':
      return <ReportIcon />
    case 'notifications':
      return <BellIcon />
    case 'settings':
      return <SettingsIcon />
    default:
      return null
  }
}

function ParentBottomNavigation() {
  const location = useLocation()
  const navigate = useNavigate()
  const mockSearch = getParentMockSearch(location.search)

  return (
    <nav className="parent-bottom-nav" aria-label="보호자 하단 탐색">
      <div className="parent-bottom-nav__items">
        {parentNavItems.map((item) => {
          const isActive = item.match.some((path) => location.pathname.startsWith(path))

          return (
            <button
              key={item.key}
              type="button"
              className={`parent-bottom-nav__item${isActive ? ' is-active' : ''}`}
              aria-current={isActive ? 'page' : undefined}
              onClick={() => navigate(`${item.path}${mockSearch}`)}
            >
              <span className="parent-bottom-nav__icon">{getNavIcon(item.key)}</span>
              <span className="parent-bottom-nav__label">{item.label}</span>
            </button>
          )
        })}
      </div>
      <span className="parent-bottom-nav__indicator" aria-hidden="true" />
    </nav>
  )
}

export default ParentBottomNavigation
